# Better approach: scan for maximal rectangles
def get_maximal_rectangles(grid):
    h, w = len(grid), len(grid[0])
    max_rects = {}

    for c_start in range(w):
        for c_end in range(c_start + 1, w):
            for r_start in range(h):
                if grid[r_start][c_start] != grid[r_start][c_end]:
                    continue
                color = grid[r_start][c_start]
                r_end = r_start
                while r_end + 1 < h:
                    valid = True
                    for c_pos in range(c_start, c_end + 1):
                        if grid[r_end + 1][c_pos] != color:
                            valid = False
                            break
                    if valid:
                        r_end += 1
                    else:
                        break

                if r_end > r_start:
                    key = (color, r_start, r_end, c_start, c_end)
                    area = (r_end - r_start + 1) * (c_end - c_start + 1)
                    if area > max_rects.get(key, 0):
                        max_rects[key] = area

    sorted_rects = sorted(max_rects.items(), key=lambda x: -x[1])
    return sorted_rects

